import React from 'react';

class FirstComponent extends React.Component {
   constructor(props) {
       super(props);
       this.state = {
           count: 0,
       }
   }
increment = () => {
       this.state.count++;
}

    render() {
        return (
            <>
                <div>
                    <h1>First Component</h1>
                    <div>
                        ${this.state.count}
                    </div>
                </div>
            </>

        );
    }
}
export default FirstComponent;
